-- Fujikyu GTFS static timetable import.
-- Source package SHA-256: BB1BF605817E7A3A65CAFFBCD019843AA0FFD5CB3B2C9FBB0444C8B3072FF87F
-- Source attribution: TokyoGTFS / mini-tokyo-3d; this is a static timetable source, not an operator realtime feed.
BEGIN;

SELECT pg_advisory_xact_lock(hashtext('pixel-tetsudo:fujikyu-gtfs:20261112'));

VALUES ('gtfs:tokyogtfs:rail.zip:BB1BF605817E7A3A65CAFFBCD019843AA0FFD5CB3B2C9FBB0444C8B3072FF87F', 'https://github.com/MKuranowski/TokyoGTFS', 'timetable', 'C', 'Static rail.zip package attributed to TokyoGTFS/mini-tokyo-3d; SHA-256 BB1BF605817E7A3A65CAFFBCD019843AA0FFD5CB3B2C9FBB0444C8B3072FF87F; calendar coverage 2026-11-02 through 2027-11-02; not an operator-issued revision and not a realtime feed.')
ON CONFLICT (source_key) DO UPDATE SET source_url=EXCLUDED.source_url, source_type=EXCLUDED.source_type, evidence_grade=EXCLUDED.evidence_grade, notes=EXCLUDED.notes;

SELECT 'FujisanrokuElectricRailway', 'Fujikyu', 'TokyoGTFS static Fujikyu rail.zip timetable; recheck against an operator edition before treating as current', e.id,
       'gtfs-rail-20261102-20271102-bb1bf605817e7a3a', DATE '2026-11-02', DATE '2027-11-02', c.calendar_urn, 'BB1BF605817E7A3A65CAFFBCD019843AA0FFD5CB3B2C9FBB0444C8B3072FF87F'
FROM public.evidence_sources e CROSS JOIN (VALUES ('odpt.Calendar:Weekday'), ('odpt.Calendar:SaturdayHoliday')) AS c(calendar_urn)
WHERE e.source_key='gtfs:tokyogtfs:rail.zip:BB1BF605817E7A3A65CAFFBCD019843AA0FFD5CB3B2C9FBB0444C8B3072FF87F'
ON CONFLICT DO NOTHING;

DO $$
DECLARE
  v_station_name text;
  station_idx integer := 0;
BEGIN
  station_idx := 0;
  v_station_name := 'Otsuki';
  IF NOT EXISTS (SELECT 1 FROM public.line_stations ls WHERE ls.line_id='Fujikyu' AND ls.station_name=v_station_name) THEN
  END IF;
  station_idx := 1;
  v_station_name := 'Kami-Otsuki';
  IF NOT EXISTS (SELECT 1 FROM public.line_stations ls WHERE ls.line_id='Fujikyu' AND ls.station_name=v_station_name) THEN
  END IF;
  station_idx := 2;
  v_station_name := 'Tanokura';
  IF NOT EXISTS (SELECT 1 FROM public.line_stations ls WHERE ls.line_id='Fujikyu' AND ls.station_name=v_station_name) THEN
  END IF;
  station_idx := 3;
  v_station_name := 'Kasei';
  IF NOT EXISTS (SELECT 1 FROM public.line_stations ls WHERE ls.line_id='Fujikyu' AND ls.station_name=v_station_name) THEN
  END IF;
  station_idx := 4;
  v_station_name := 'Akasaka-Fujikyu';
  IF NOT EXISTS (SELECT 1 FROM public.line_stations ls WHERE ls.line_id='Fujikyu' AND ls.station_name=v_station_name) THEN
  END IF;
  station_idx := 5;
  v_station_name := 'Tsuru-shi';
  IF NOT EXISTS (SELECT 1 FROM public.line_stations ls WHERE ls.line_id='Fujikyu' AND ls.station_name=v_station_name) THEN
  END IF;
  station_idx := 6;
  v_station_name := 'Yamuramachi';
  IF NOT EXISTS (SELECT 1 FROM public.line_stations ls WHERE ls.line_id='Fujikyu' AND ls.station_name=v_station_name) THEN
  END IF;
  station_idx := 7;
  v_station_name := 'Tsurubunkadaigaku-mae';
  IF NOT EXISTS (SELECT 1 FROM public.line_stations ls WHERE ls.line_id='Fujikyu' AND ls.station_name=v_station_name) THEN
  END IF;
  station_idx := 8;
  v_station_name := 'Tokaichiba-Fujikyu';
  IF NOT EXISTS (SELECT 1 FROM public.line_stations ls WHERE ls.line_id='Fujikyu' AND ls.station_name=v_station_name) THEN
  END IF;
  station_idx := 9;
  v_station_name := 'Higashi-Katsura';
  IF NOT EXISTS (SELECT 1 FROM public.line_stations ls WHERE ls.line_id='Fujikyu' AND ls.station_name=v_station_name) THEN
  END IF;
  station_idx := 10;
  v_station_name := 'Mitsutoge';
  IF NOT EXISTS (SELECT 1 FROM public.line_stations ls WHERE ls.line_id='Fujikyu' AND ls.station_name=v_station_name) THEN
  END IF;
  station_idx := 11;
  v_station_name := 'Kotobuki';
  IF NOT EXISTS (SELECT 1 FROM public.line_stations ls WHERE ls.line_id='Fujikyu' AND ls.station_name=v_station_name) THEN
  END IF;
  station_idx := 12;
  v_station_name := 'Yoshiikeonsenmae';
  IF NOT EXISTS (SELECT 1 FROM public.line_stations ls WHERE ls.line_id='Fujikyu' AND ls.station_name=v_station_name) THEN
  END IF;
  station_idx := 13;
  v_station_name := 'Shimoyoshida';
  IF NOT EXISTS (SELECT 1 FROM public.line_stations ls WHERE ls.line_id='Fujikyu' AND ls.station_name=v_station_name) THEN
  END IF;
  station_idx := 14;
  v_station_name := 'Gekkoji';
  IF NOT EXISTS (SELECT 1 FROM public.line_stations ls WHERE ls.line_id='Fujikyu' AND ls.station_name=v_station_name) THEN
  END IF;
  station_idx := 15;
  v_station_name := 'Fujisan';
  IF NOT EXISTS (SELECT 1 FROM public.line_stations ls WHERE ls.line_id='Fujikyu' AND ls.station_name=v_station_name) THEN
  END IF;
  station_idx := 16;
  v_station_name := 'Fujikyu-Highland';
  IF NOT EXISTS (SELECT 1 FROM public.line_stations ls WHERE ls.line_id='Fujikyu' AND ls.station_name=v_station_name) THEN
  END IF;
  station_idx := 17;
  v_station_name := 'Kawaguchiko';
  IF NOT EXISTS (SELECT 1 FROM public.line_stations ls WHERE ls.line_id='Fujikyu' AND ls.station_name=v_station_name) THEN
  END IF;
END $$;

CREATE TEMP TABLE _fujikyu_gtfs_seed(
  trip_id text PRIMARY KEY,
  calendar_name text NOT NULL,
  train_number text NOT NULL,
  direction_name text NOT NULL,
  destination_station text NOT NULL,
  stops jsonb NOT NULL
) ON COMMIT DROP;


  line_key, calendar_urn, train_number, railway_urn, direction_urn, train_type_urn, destination_urns, vehicle_type_label, source_path, source_occurrence, source_trip_id, revision_id
)
SELECT 'Fujikyu', 'odpt.Calendar:'||s.calendar_name, s.train_number,
       'odpt.Railway:FujisanrokuElectricRailway.Fujikyu', 'odpt.RailDirection:'||s.direction_name,
       'odpt.TrainType:FujisanrokuElectricRailway.Local',
       ARRAY['odpt.Station:FujisanrokuElectricRailway.Fujikyu.'||s.destination_station]::text[],
       NULL, 'gtfs:tokyogtfs:rail.zip:BB1BF605817E7A3A65CAFFBCD019843AA0FFD5CB3B2C9FBB0444C8B3072FF87F:Fujikyu.Fujikyu', 0, s.trip_id, r.id
FROM _fujikyu_gtfs_seed s
JOIN public.timetable_revisions r ON r.line_id='Fujikyu' AND r.calendar_urn='odpt.Calendar:'||s.calendar_name
  AND r.version_key='gtfs-rail-20261102-20271102-bb1bf605817e7a3a'
ON CONFLICT DO NOTHING;

SELECT t.id, x.ordinality::integer,
       'odpt.Station:FujisanrokuElectricRailway.Fujikyu.'||(x.stop->>'station'),
       'odpt.Station:FujisanrokuElectricRailway.Fujikyu.'||(x.stop->>'station'),
       x.stop->>'arrival', x.stop->>'departure'
FROM _fujikyu_gtfs_seed s
JOIN public.manual_timetable_templates t ON t.line_key='Fujikyu' AND t.source_trip_id=s.trip_id AND t.source_path='gtfs:tokyogtfs:rail.zip:BB1BF605817E7A3A65CAFFBCD019843AA0FFD5CB3B2C9FBB0444C8B3072FF87F:Fujikyu.Fujikyu'
CROSS JOIN LATERAL jsonb_array_elements(s.stops) WITH ORDINALITY AS x(stop, ordinality)
ON CONFLICT DO NOTHING;

SELECT 'fujikyu:gtfs:'||t.id, t.calendar_urn, t.train_number, t.id, 'source_only', 'undated_not_current_verified'
FROM public.manual_timetable_templates t
WHERE t.line_key='Fujikyu' AND t.source_path='gtfs:tokyogtfs:rail.zip:BB1BF605817E7A3A65CAFFBCD019843AA0FFD5CB3B2C9FBB0444C8B3072FF87F:Fujikyu.Fujikyu'
  AND NOT EXISTS (SELECT 1 FROM public.train_timetables c WHERE c.lead_source_template_id=t.id);

SELECT t.id, c.id, 0, 'primary', 0, (SELECT max(stop_sequence) FROM public.manual_timetable_template_stops s WHERE s.template_id=t.id), 0, false
FROM public.manual_timetable_templates t
JOIN public.train_timetables c ON c.lead_source_template_id=t.id
WHERE t.line_key='Fujikyu' AND t.source_path='gtfs:tokyogtfs:rail.zip:BB1BF605817E7A3A65CAFFBCD019843AA0FFD5CB3B2C9FBB0444C8B3072FF87F:Fujikyu.Fujikyu'
  AND NOT EXISTS (SELECT 1 FROM public.train_timetable_members m WHERE m.timetable_id=c.id AND m.source_template_id=t.id);

UPDATE public.railway_lines
SET sql_planned_fallback_enabled=true, timetable_api_enabled=false, realtime_position_api_enabled=false
WHERE id='Fujikyu';

UPDATE public.published_timetable_coverage_audit a
SET template_count=s.template_count, calendar_count=s.calendar_count, direction_count=s.direction_count, sampled_count=s.sampled_count,
    coverage_status='unverified',
    issues=ARRAY['GTFS_STATIC_SOURCE_NOT_OPERATOR_EDITION','FUTURE_EDITION_DATE_RECHECK_REQUIRED','NO_REALTIME_SOURCE']::text[], checked_at=now()
FROM (
  SELECT count(*)::integer AS template_count, count(DISTINCT calendar_urn)::integer AS calendar_count,
         count(DISTINCT direction_urn)::integer AS direction_count, 0::integer AS sampled_count
  FROM public.manual_timetable_templates WHERE line_key='Fujikyu' AND source_path='gtfs:tokyogtfs:rail.zip:BB1BF605817E7A3A65CAFFBCD019843AA0FFD5CB3B2C9FBB0444C8B3072FF87F:Fujikyu.Fujikyu'
) s WHERE a.line_key='Fujikyu';

DO $$
DECLARE
  template_count integer;
  stop_count integer;
  line_station_count integer;
BEGIN
  SELECT count(*) INTO template_count FROM public.manual_timetable_templates WHERE line_key='Fujikyu' AND source_path='gtfs:tokyogtfs:rail.zip:BB1BF605817E7A3A65CAFFBCD019843AA0FFD5CB3B2C9FBB0444C8B3072FF87F:Fujikyu.Fujikyu';
  SELECT count(*) INTO stop_count FROM public.manual_timetable_template_stops s JOIN public.manual_timetable_templates t ON t.id=s.template_id WHERE t.line_key='Fujikyu' AND t.source_path='gtfs:tokyogtfs:rail.zip:BB1BF605817E7A3A65CAFFBCD019843AA0FFD5CB3B2C9FBB0444C8B3072FF87F:Fujikyu.Fujikyu';
  SELECT count(*) INTO line_station_count FROM public.line_stations WHERE line_id='Fujikyu';
  IF template_count <> 152 THEN RAISE EXCEPTION 'Fujikyu GTFS template count mismatch: %', template_count; END IF;
  IF stop_count <> 2304 THEN RAISE EXCEPTION 'Fujikyu GTFS stop count mismatch: %', stop_count; END IF;
  IF line_station_count <> 18 THEN RAISE EXCEPTION 'Fujikyu line station count mismatch: %', line_station_count; END IF;
END $$;

COMMIT;
